def version_tuple(value):
    if not isinstance(value, str) or not re.fullmatch(r'v(0|[1-9][0-9]{0,5})\.(0|[1-9][0-9]{0,5})\.(0|[1-9][0-9]{0,5})', value):
        raise ValueError('Numéro de version invalide : format attendu v0.0.1.')
    return tuple(int(part) for part in value[1:].split('.'))


def update_snapshot():
    with UPDATE_LOCK:
        return {**UPDATE_STATE, 'current': APP_VERSION, 'instance': INSTANCE_ID,
                'preview': PREVIEW, 'restart_notice': RESTART_NOTICE}


def update_state(**values):
    with UPDATE_LOCK:
        UPDATE_STATE.update(values)


class GitHubRedirects(HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        validate_github_url(newurl)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def validate_github_url(url):
    parsed = urlparse(url)
    if (parsed.scheme != 'https' or parsed.hostname not in
            ('api.github.com', 'github.com', 'release-assets.githubusercontent.com', 'objects.githubusercontent.com')
            or parsed.username or parsed.password or parsed.port not in (None, 443)):
        raise ValueError('Adresse de téléchargement GitHub non autorisée.')


def github_bytes(url, limit, accept):
    validate_github_url(url)
    req = Request(url, headers={'Accept': accept, 'User-Agent': 'Dominis/' + APP_VERSION,
                               'X-GitHub-Api-Version': '2022-11-28'})
    deadline = time.monotonic() + 60
    with build_opener(GitHubRedirects()).open(req, timeout=12) as response:
        validate_github_url(response.url)
        length = response.headers.get('Content-Length')
        if length and int(length) > limit: raise ValueError('Fichier de mise à jour trop volumineux.')
        data = bytearray()
        while True:
            if time.monotonic() > deadline: raise TimeoutError('Délai de téléchargement dépassé.')
            chunk = response.read(min(65536, limit + 1 - len(data)))
            if not chunk: break
            data.extend(chunk)
            if len(data) > limit: raise ValueError('Fichier de mise à jour trop volumineux.')
        return bytes(data)


def release_info(data):
    if not isinstance(data, dict) or data.get('draft') or data.get('prerelease'):
        raise ValueError('La Release doit être publiée et stable.')
    tag = data.get('tag_name')
    version_tuple(tag)
    assets = [a for a in data.get('assets', []) if a.get('name') == 'Dominis.py' and a.get('state') == 'uploaded']
    if len(assets) != 1: raise ValueError('La Release doit contenir le fichier joint Dominis.py.')
    asset = assets[0]
    expected = RELEASE_DOWNLOADS + tag + '/Dominis.py'
    if asset.get('browser_download_url') != expected:
        raise ValueError('Le fichier doit appartenir à la Release officielle Dominis.')
    size = asset.get('size')
    if not isinstance(size, int) or not 0 < size <= MAX_UPDATE_BYTES:
        raise ValueError('Taille du fichier de mise à jour invalide.')
    digest = asset.get('digest')
    if digest is not None and not re.fullmatch(r'sha256:[0-9a-fA-F]{64}', digest):
        raise ValueError('Empreinte GitHub non prise en charge.')
    return {'version': tag, 'url': expected, 'size': size, 'digest': digest}


def check_updates():
    global UPDATE_RELEASE
    try:
        raw = github_bytes(RELEASES_API, 1024 * 1024, 'application/vnd.github+json')
        data = json.loads(raw)
        # Une version égale ou plus ancienne ne déclenche jamais de proposition.
        tag = data.get('tag_name') if isinstance(data, dict) else None
        version_tuple(tag)
        if data.get('draft') or data.get('prerelease'): raise ValueError('Release non stable.')
        if version_tuple(tag) <= version_tuple(APP_VERSION):
            UPDATE_RELEASE = None
            update_state(status='current', latest=tag, checked_at=now(), message='Dominis est à jour.')
        else:
            release = release_info(data)
            with UPDATE_LOCK:
                UPDATE_RELEASE = release
                UPDATE_STATE.update(status='available', latest=tag, checked_at=now(), message='Une nouvelle version est disponible.')
    except HTTPError as e:
        message = ('Aucune Release publique accessible pour le moment.' if e.code == 404 else
                   'GitHub limite les vérifications. Réessayez plus tard.' if e.code in (403, 429) else
                   'GitHub ne répond pas correctement. Réessayez plus tard.')
        update_state(status='unavailable', checked_at=now(), message=message)
    except Exception as e:
        update_state(status='unavailable', checked_at=now(), message='Vérification impossible : ' + str(e))


def start_update_check():
    with UPDATE_LOCK:
        if PREVIEW:
            UPDATE_STATE.update(status='disabled', message='Les mises à jour sont désactivées dans l’aperçu.')
            return
        if UPDATE_BUSY.is_set() or UPDATE_STATE['status'] == 'checking': return
        UPDATE_STATE.update(status='checking', message='Vérification sur GitHub…')
    threading.Thread(target=check_updates, daemon=True).start()


def validate_update_source(raw, expected):
    if not raw or len(raw) > MAX_UPDATE_BYTES: raise ValueError('Fichier de mise à jour vide ou trop volumineux.')
    # Analyse et compilation sans exécuter le code téléchargé.
    tree = ast.parse(raw, filename='Dominis.py')
    compile(tree, 'Dominis.py', 'exec', dont_inherit=True)
    wanted = {'APP_VERSION', 'UPDATE_PROTOCOL', 'DB_SCHEMA_VERSION', 'MIN_PYTHON'}
    metadata = {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id in wanted:
                    if target.id in metadata: raise ValueError('Métadonnée de version déclarée plusieurs fois.')
                    metadata[target.id] = ast.literal_eval(node.value)
    if metadata.get('APP_VERSION') != expected: raise ValueError('La version du script ne correspond pas au tag GitHub.')
    version_tuple(expected)
    if metadata.get('UPDATE_PROTOCOL') != UPDATE_PROTOCOL: raise ValueError('Cette version nécessite une installation manuelle (protocole différent).')
    if metadata.get('DB_SCHEMA_VERSION') != DB_SCHEMA_VERSION: raise ValueError('Cette version nécessite une migration de données non prise en charge automatiquement.')
    minimum = metadata.get('MIN_PYTHON')
    if (not isinstance(minimum, tuple) or len(minimum) != 2 or
            not all(type(v) is int and v >= 0 for v in minimum) or sys.version_info[:2] < minimum):
        raise ValueError('La version de Python installée ne convient pas à cette mise à jour.')


def durable_write(path, data, mode=0o600):
    with open(path, 'xb') as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.chmod(path, mode)


def stage_update(release, target=None):
    target = Path(target) if target else Path(__file__).absolute()
    if target.name != 'Dominis.py' or target.is_symlink():
        raise ValueError('Le programme doit être un fichier Dominis.py, pas un lien symbolique.')
    raw = github_bytes(release['url'], MAX_UPDATE_BYTES, 'application/octet-stream')
    if len(raw) != release['size']: raise ValueError('Téléchargement incomplet : taille différente de celle annoncée.')
    if release.get('digest') and hashlib.sha256(raw).hexdigest() != release['digest'].split(':', 1)[1].lower():
        raise ValueError('L’empreinte du fichier ne correspond pas à celle de GitHub.')
    validate_update_source(raw, release['version'])
    folder = Path(tempfile.mkdtemp(prefix='.dominis-update-', dir=target.parent))
    try:
        mode = target.stat().st_mode & 0o777
        durable_write(folder / 'candidate.tmp', raw, mode)
        previous = target.read_bytes()
        durable_write(folder / 'previous.tmp', previous, mode)
        return {'folder': folder, 'target': target, 'version': release['version'],
                'previous_hash': hashlib.sha256(previous).hexdigest()}
    except Exception:
        shutil.rmtree(folder, ignore_errors=True)
        raise


def close_for_update():
    EXIT_READY.set()
    if WINDOW: WINDOW.destroy()
    else: SERVER.shutdown()


def install_update():
    global PENDING_UPDATE
    plan = None
    try:
        with UPDATE_LOCK: release = dict(UPDATE_RELEASE)
        plan = stage_update(release)
        update_state(status='installing', message='Fichier vérifié. Sauvegarde de vos données…')
        with LOCK:
            with connect() as c:
                if c.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
                    raise ValueError('L’intégrité de data.db doit être rétablie avant toute mise à jour.')
            # Obligatoire, même si la sauvegarde habituelle à la fermeture est désactivée.
            make_safety_backup()
            PENDING_UPDATE = plan
        update_state(status='restarting', message='Installation prête. Redémarrage automatique en cours…')
        # Laisse à l’interface le temps d’afficher la transition avant de fermer le serveur.
        time.sleep(1.5)
        close_for_update()
    except Exception as e:
        PENDING_UPDATE = None
        if plan: shutil.rmtree(plan['folder'], ignore_errors=True)
        EXIT_READY.clear()
        UPDATE_BUSY.clear()
        update_state(status='failed', message='Mise à jour annulée : ' + str(e))


def start_update_install():
    # Appelé sous LOCK pour attendre les écritures déjà engagées avant de les bloquer.
    with UPDATE_LOCK:
        if PREVIEW: raise ValueError('Installation désactivée dans l’aperçu.')
        if UPDATE_BUSY.is_set(): raise ValueError('Une mise à jour est déjà en cours.')
        if NATIVE_CLOSE_LOCK.locked(): raise ValueError('Une fermeture est déjà en cours.')
        if UPDATE_STATE['status'] not in ('available', 'failed') or not UPDATE_RELEASE:
            raise ValueError('Aucune mise à jour installable. Vérifiez à nouveau les versions.')
        UPDATE_BUSY.set()
        UPDATE_STATE.update(status='downloading', message='Téléchargement sécurisé de Dominis.py…', dismissed=True)
    threading.Thread(target=install_update, daemon=True).start()


class InstanceGuard:
    """Une seule instance locale par dossier du programme, même sur un autre port."""
    def __init__(self, folder):
        self.file = open(Path(folder) / '.dominis-instance.lock', 'a+b')
        try:
            self.file.seek(0, 2)
            if self.file.tell() == 0:
                self.file.write(b'0'); self.file.flush()
            self.file.seek(0)
            if os.name == 'nt':
                import msvcrt
                msvcrt.locking(self.file.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(self.file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except Exception:
            self.file.close()
            raise

    def close(self):
        self.file.close()  # La fermeture libère le verrou sur les deux plateformes.


def signal_update_ready():
    path = os.environ.pop('DOMINIS_UPDATE_READY', None)
    nonce = os.environ.pop('DOMINIS_UPDATE_NONCE', None)
    if path and nonce:
        ready = Path(path)
        temp = ready.with_suffix('.tmp')
        durable_write(temp, json.dumps({'version': APP_VERSION, 'nonce': nonce}).encode())
        os.replace(temp, ready)


def launch_updated(plan, timeout=60):
    """Le processus actuel surveille le redémarrage et garde le lanceur Terminal vivant."""
    global INSTANCE_GUARD
    folder, target = plan['folder'], plan['target']
    child = None
    replaced = False
    ready = folder / 'ready.json'
    nonce = secrets.token_hex(24)
    env = os.environ.copy()
    for key in ('DOMINIS_UPDATE_READY', 'DOMINIS_UPDATE_NONCE', 'DOMINIS_UPDATE_NOTICE'):
        env.pop(key, None)
    child_env = {**env, 'DOMINIS_UPDATE_READY': str(ready), 'DOMINIS_UPDATE_NONCE': nonce,
                 'DOMINIS_UPDATE_NOTICE': json.dumps({'kind': 'success', 'version': plan['version']})}
    command = [sys.executable, str(target), *START_ARGS]
    # Le navigateur déjà ouvert attend le nouveau serveur ; ne pas créer un second onglet.
    if '--desktop' not in START_ARGS and '--no-browser' not in command: command.append('--no-browser')
    try:
        if hashlib.sha256(target.read_bytes()).hexdigest() != plan['previous_hash']:
            raise ValueError('Dominis.py a changé pendant le téléchargement. Remplacement annulé.')
        # Atomique : candidate.tmp et Dominis.py résident sur le même système de fichiers.
        os.replace(folder / 'candidate.tmp', target)
        replaced = True
        if INSTANCE_GUARD:
            INSTANCE_GUARD.close(); INSTANCE_GUARD = None
        child = subprocess.Popen(command, cwd=str(target.parent), env=child_env)
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if child.poll() is not None: raise RuntimeError('La nouvelle version s’est arrêtée au démarrage.')
            if ready.exists():
                receipt = json.loads(ready.read_text())
                if receipt == {'version': plan['version'], 'nonce': nonce}: break
            time.sleep(.1)
        else: raise TimeoutError('La nouvelle version n’a pas confirmé son démarrage.')
    except Exception as e:
        print('Mise à jour non finalisée : ' + str(e), flush=True)
        if child and child.poll() is None:
            child.terminate()
            try: child.wait(timeout=10)
            except subprocess.TimeoutExpired: child.kill(); child.wait()
        try:
            if replaced: os.replace(folder / 'previous.tmp', target)
            if INSTANCE_GUARD:
                INSTANCE_GUARD.close(); INSTANCE_GUARD = None
            recovery_env = {**env, 'DOMINIS_UPDATE_NOTICE': json.dumps({
                'kind': 'rollback', 'message': 'La mise à jour a échoué. La version précédente a été conservée. ' + str(e)})}
            child = subprocess.Popen(command, cwd=str(target.parent), env=recovery_env)
        except Exception as recovery_error:
            # Conserver previous.tmp si le disque refuse la restauration ; ne jamais toucher à la base.
            print('Redémarrage impossible : ' + str(recovery_error) + '\nFichiers de récupération : ' + str(folder), flush=True)
            return 1
    shutil.rmtree(folder, ignore_errors=True)
    # Le shell du lanceur ne se termine qu’à la fermeture de la nouvelle application.
    try: return child.wait()
    except KeyboardInterrupt:
        # Ctrl+C est également reçu par l’enfant qui assure sa propre fermeture.
        return child.wait()


def run_application():
    global INSTANCE_GUARD, START_ARGS, RESTART_NOTICE
    # Conserver le chemin absolu de la base, même pour un lancement depuis un autre dossier.
    args = sys.argv[1:]
    START_ARGS = list(args)
    notice = os.environ.pop('DOMINIS_UPDATE_NOTICE', None)
    if notice:
        try: RESTART_NOTICE = json.loads(notice)
        except ValueError: pass
    try:
        if '--preview' not in args:
            try: INSTANCE_GUARD = InstanceGuard(ROOT)
            except OSError:
                print('Dominis est déjà ouvert, ou son dossier n’est pas accessible en écriture.', flush=True)
                return 1
        result = main()
        if PENDING_UPDATE and result == 0:
            # Éviter la réinjection de données de démonstration et les chemins relatifs au redémarrage.
            START_ARGS = ['--db', str(DB), '--host', START_HOST, '--port', str(START_PORT)] + (
                ['--desktop'] if START_DESKTOP else []) + (['--no-browser'] if START_NO_BROWSER else [])
            return launch_updated(PENDING_UPDATE)
        return result
    finally:
        if INSTANCE_GUARD:
            INSTANCE_GUARD.close(); INSTANCE_GUARD = None


def uid(): return uuid.uuid4().hex

def now(): return dt.datetime.now().isoformat(timespec='seconds')

class ClosingConnection(sqlite3.Connection):
    def __exit__(self, exc_type, exc_value, traceback):
        try: return super().__exit__(exc_type, exc_value, traceback)
        finally: self.close()

def connect(path=None):
    c = sqlite3.connect(str(path or DB), timeout=20, factory=ClosingConnection)
    c.row_factory = sqlite3.Row
    c.execute('PRAGMA foreign_keys=ON')
    c.execute('PRAGMA synchronous=FULL')
    return c

def init_db():
    DB.parent.mkdir(parents=True, exist_ok=True)
    with connect() as c:
        c.executescript('''CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS scis(id TEXT PRIMARY KEY,data TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,sci TEXT NOT NULL REFERENCES scis(id) ON DELETE CASCADE,kind TEXT NOT NULL,data TEXT NOT NULL);
        CREATE INDEX IF NOT EXISTS records_scope ON records(sci,kind);
        CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,at TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS imports(fingerprint TEXT PRIMARY KEY,at TEXT NOT NULL);
        ''')
        c.execute('INSERT OR IGNORE INTO meta VALUES(?,?)',('version','1'))
        c.execute('INSERT OR IGNORE INTO meta VALUES(?,?)',('settings',json.dumps(DEFAULTS)))

def settings(c):
    r=c.execute("SELECT value FROM meta WHERE key='settings'").fetchone()
    return {**DEFAULTS, **json.loads(r[0])}

def audit(c,action,detail): c.execute('INSERT INTO audit(at,action,detail) VALUES(?,?,?)',(now(),action,str(detail)[:500]))

def unpack(r): return {**json.loads(r['data']), 'id':r['id'], **({'sci':r['sci'],'kind':r['kind']} if 'sci' in r.keys() else {})}

def state(c):
    records=[]
    for r in c.execute('SELECT * FROM records ORDER BY rowid'):
        d=unpack(r); d.pop('blob',None); records.append(d)
    return {'scis':[unpack(r) for r in c.execute('SELECT * FROM scis ORDER BY rowid')], 'records':records, 'settings':settings(c),'audit':[dict(r) for r in c.execute('SELECT * FROM audit ORDER BY id DESC LIMIT 80')], 'preview':PREVIEW,'native':WINDOW is not None,'db_size':DB.stat().st_size,'saved_at':now(),'app_version':APP_VERSION}

def clean(kind,data):
    if not isinstance(data,dict): raise ValueError('Données invalides.')
    d={k:v for k,v in data.items() if k not in ('id','sci','kind')}
    required={'sci':['name'],'properties':['name','address'],'leases':['tenant','property_id','start'],'partners':['name'],'loans':['name'],'calls':['lease_id','period','due'],'entries':['label','date','direction'],'tasks':['name','due'],'documents':['name']}
    for f in required.get(kind,[]):
        if not str(d.get(f,'')).strip(): raise ValueError('Champ obligatoire : '+f)
    for k,v in list(d.items()):
        if not isinstance(v,(str,int,float,bool,type(None))): raise ValueError('Valeur non prise en charge : '+k)
        if isinstance(v,str) and k!='blob' and len(v)>30000: raise ValueError('Texte trop long.')
    amounts=['capital','opening','value','purchase','surface','rent','charges','deposit','shares','cca','principal','balance','rate','monthly','amount','paid','interest','insurance']
    for f in amounts:
        if f in d:
            try:
                from decimal import Decimal, InvalidOperation
                v=Decimal(str(d[f] or 0))
                if not v.is_finite() or abs(v)>Decimal('1000000000000'): raise ValueError('Montant hors limites.')
                if f not in ('opening','cca') and v<0: raise ValueError('Le montant doit être positif : '+f)
                d[f]=float(v.quantize(Decimal('0.01')))
            except (InvalidOperation,TypeError): raise ValueError('Montant invalide : '+f)
    for f in ['date','due','start','end','acquired','dpe_date','balance_date','opening_date']:
        if d.get(f):
            try: dt.date.fromisoformat(d[f])
            except (ValueError,TypeError): raise ValueError('Date invalide : '+f)
    if d.get('end') and d.get('start') and d['end']<d['start']: raise ValueError('La fin précède le début du bail.')
    if kind=='sci':
        if d.get('regime','IR') not in ['IR','IS']: raise ValueError('Régime fiscal invalide.')
        if d.get('siren') and (not d['siren'].isdigit() or len(d['siren'])!=9): raise ValueError('Le SIREN doit comporter 9 chiffres.')
        if not d.get('opening_date'): d['opening_date']='2000-01-01'
    if kind=='entries' and d.get('direction') not in ['Recette','Dépense']: raise ValueError('Sens invalide.')
    if kind=='calls':
        try: dt.date.fromisoformat(d['period']+'-01')
        except (ValueError,TypeError): raise ValueError('Période invalide.')
    if kind=='documents' and d.get('blob'):
        try: raw=base64.b64decode(d['blob'],validate=True)
        except Exception: raise ValueError('Pièce jointe invalide.')
        if len(raw)>12*1024*1024: raise ValueError('Pièce jointe limitée à 12 Mo.')
        d['size']=len(raw)
    return d

REFS={'property_id':'properties','lease_id':'leases','call_id':'calls'}
def validate_refs(c,sci,d,ident=''):
    for f,k in REFS.items():
        if d.get(f):
            r=c.execute('SELECT * FROM records WHERE id=? AND sci=? AND kind=?',(d[f],sci,k)).fetchone()
            if not r: raise ValueError('Lien invalide ou appartenant à une autre SCI : '+f)
    if d.get('call_id'):
        call=unpack(c.execute('SELECT * FROM records WHERE id=?',(d['call_id'],)).fetchone())
        if d.get('direction')!='Recette': raise ValueError('Un encaissement de loyer doit être une recette.')
        paid=sum(json.loads(r[0]).get('amount',0) for r in c.execute("SELECT data FROM records WHERE kind='entries' AND sci=? AND id<>?",(sci,ident)) if json.loads(r[0]).get('call_id')==d['call_id'])
        if round(paid+d.get('amount',0),2)>round(call.get('rent',0)+call.get('charges',0),2): raise ValueError('Le paiement dépasse le solde de cet appel de loyer.')

def save_record(c,p):
    kind=p['kind']; sci=p.get('sci'); ident=p.get('id') or uid(); updating=bool(p.get('id'))
    if kind!='sci' and kind not in KINDS: raise ValueError('Type inconnu.')
    d=clean(kind,p['data'])
    table='scis' if kind=='sci' else 'records'
    previous=c.execute('SELECT * FROM '+table+' WHERE id=?',(ident,)).fetchone()
    if updating and not previous: raise ValueError('Cet élément a été supprimé. Actualisez la page.')
    if kind=='sci':
        c.execute('INSERT INTO scis(id,data) VALUES(?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data',(ident,json.dumps(d)))
    else:
        if not c.execute('SELECT id FROM scis WHERE id=?',(sci,)).fetchone(): raise ValueError('SCI introuvable.')
        if previous and previous['sci']!=sci: raise ValueError('Impossible de changer la SCI.')
        if kind=='documents' and previous and not d.get('blob'):
            old=json.loads(previous['data']); d.update({k:old[k] for k in ['blob','size','filename','mime'] if k in old})
        validate_refs(c,sci,d,ident)
        if kind=='calls':
            for r in c.execute("SELECT * FROM records WHERE sci=? AND kind='calls' AND id<>?",(sci,ident)):
                old=json.loads(r['data'])
                if old.get('lease_id')==d.get('lease_id') and old.get('period')==d.get('period'): raise ValueError('Un appel existe déjà pour ce bail et ce mois.')
            paid=sum(json.loads(r[0]).get('amount',0) for r in c.execute("SELECT data FROM records WHERE kind='entries' AND sci=?",(sci,)) if json.loads(r[0]).get('call_id')==ident)
            if previous and paid>0 and any(json.loads(previous['data']).get(f)!=d.get(f) for f in ['lease_id','period']): raise ValueError('Un appel déjà encaissé ne peut pas changer de bail ou de période.')
            if round(d.get('rent',0)+d.get('charges',0),2)<round(paid,2): raise ValueError('Le montant appelé est inférieur aux paiements déjà enregistrés.')
        c.execute('INSERT INTO records VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET data=excluded.data',(ident,sci,kind,json.dumps(d)))
    audit(c,'Modification' if previous else 'Création',d.get('name') or d.get('label') or d.get('tenant') or kind)
    return ident

def backup_bytes(c):
    fd,p=tempfile.mkstemp(suffix='.db'); os.close(fd)
    try:
        dst=sqlite3.connect(p); c.backup(dst); dst.close()
        return Path(p).read_bytes()
    finally: Path(p).unlink(missing_ok=True)

def make_safety_backup():
    folder=DB.parent/'sauvegardes'; folder.mkdir(exist_ok=True)
    with connect() as c: raw=backup_bytes(c)
    durable_write(folder/('dominis-'+dt.datetime.now().strftime('%Y%m%d-%H%M%S-%f')+'.db'), raw)

def export_bundle(c,p):
    ids=p.get('scis',[]); kinds=p.get('kinds',[])
    if not ids or not kinds: raise ValueError('Sélectionnez au moins une SCI et un type de données.')
    allrows=[unpack(r) for r in c.execute('SELECT * FROM records') if r['sci'] in ids]
    chosen={r['id']:r for r in allrows if r['kind'] in kinds}
    # Inclure les dépendances pour obtenir un export réimportable.
    lookup={r['id']:r for r in allrows}
    changed=True
    while changed:
        changed=False
        for r in list(chosen.values()):
            for f in REFS:
                if r.get(f) in lookup and r[f] not in chosen: chosen[r[f]]=lookup[r[f]]; changed=True
    return {'application':'Dominis','version':1,'exported_at':now(),'scis':[unpack(r) for r in c.execute('SELECT * FROM scis') if r['id'] in ids], 'records':list(chosen.values())}

def parse_import(p):
    fmt=p.get('format','json')
    if fmt=='json':
        try: b=json.loads(p['text'])
        except Exception: raise ValueError('Fichier JSON illisible.')
        if not isinstance(b,dict) or b.get('application') not in ('Dominis','Aurea') or b.get('version')!=1: raise ValueError('Choisissez un export JSON Dominis (ou Auréa) au format version 1.')
        if not isinstance(b.get('scis'),list) or not isinstance(b.get('records'),list): raise ValueError('Export incomplet.')
        if len(b['records'])>40000: raise ValueError('Import limité à 40 000 lignes.')
        ids=set()
        for s in b['scis']:
            if not s.get('id') or s['id'] in ids: raise ValueError('Identifiants SCI invalides.')
            ids.add(s['id']); clean('sci',s)
        seen=set()
        for r in b['records']:
            if r.get('kind') not in KINDS or r.get('sci') not in ids or not r.get('id') or r['id'] in seen: raise ValueError('Références invalides dans cet export.')
            seen.add(r['id']); clean(r['kind'],r)
        return b
    if fmt!='csv': raise ValueError('Format non pris en charge.')
    text=p.get('text','').lstrip('\ufeff')
    try: dialect=csv.Sniffer().sniff(text[:4000],delimiters=';,\t')
    except csv.Error: dialect=csv.excel; dialect.delimiter=';'
    reader=csv.DictReader(io.StringIO(text),dialect=dialect)
    if not set(['date','label','direction','category','amount']).issubset(reader.fieldnames or []): raise ValueError('En-têtes requis : date;label;direction;category;amount')
    rows=[]; sources={}
    for i,r in enumerate(reader,2):
        try:
            d={k:r.get(k,'') for k in ['date','label','direction','category','amount']}
            d['amount']=float(d['amount'].replace(' ','').replace(',','.'))
            name=(r.get('sci') or '').strip()
            source='csv_'+hashlib.sha256(name.encode()).hexdigest()[:16] if name else 'csv'
            sources[source]={'id':source,'name':name or 'Mouvements CSV sans société renseignée'}
            rows.append({**clean('entries',d),'id':uid(),'sci':source,'kind':'entries'})
        except Exception as e: raise ValueError('Ligne '+str(i)+' : '+str(e))
    if not rows or len(rows)>40000: raise ValueError('Le CSV doit contenir entre 1 et 40 000 lignes.')
    return {'application':'Dominis','version':1,'scis':list(sources.values()),'records':rows}

def import_bundle(c,p):
    b=parse_import(p); mapping=p.get('mapping',{})
    selected=[s for s in b['scis'] if s['id'] in mapping]
    if not selected: raise ValueError('Sélectionnez les SCI à importer et leur destination.')
    if p.get('format')=='csv' and any(dest=='new' for dest in mapping.values()): raise ValueError('Sélectionnez une SCI existante pour le CSV.')
    fp=hashlib.sha256((p['text']+json.dumps(mapping,sort_keys=True)).encode()).hexdigest()
    if c.execute('SELECT 1 FROM imports WHERE fingerprint=?',(fp,)).fetchone(): raise ValueError('Ce fichier a déjà été importé vers ces destinations.')
    sci_map={}
    for s in selected:
        dest=mapping[s['id']]
        if dest=='new':
            d=clean('sci',s); d['name']=d['name']+' (import)'; new=uid()
            c.execute('INSERT INTO scis VALUES(?,?)',(new,json.dumps(d))); sci_map[s['id']]=new
        else:
            if not c.execute('SELECT 1 FROM scis WHERE id=?',(dest,)).fetchone(): raise ValueError('SCI de destination introuvable.')
            sci_map[s['id']]=dest
    rows=[r for r in b['records'] if r['sci'] in sci_map]
    idmap={r['id']:uid() for r in rows}
    for r in rows:
        d=clean(r['kind'],r)
        for f in REFS:
            if d.get(f):
                if d[f] not in idmap: raise ValueError('Dépendance absente : '+f+'. Exportez aussi les données liées.')
                d[f]=idmap[d[f]]
        c.execute('INSERT INTO records VALUES(?,?,?,?)',(idmap[r['id']],sci_map[r['sci']],r['kind'],json.dumps(d)))
    for r in rows:
        v=c.execute('SELECT * FROM records WHERE id=?',(idmap[r['id']],)).fetchone()
        validate_refs(c,v['sci'],json.loads(v['data']),v['id'])
    c.execute('INSERT INTO imports VALUES(?,?)',(fp,now())); audit(c,'Import',str(len(rows))+' éléments / '+str(len(selected))+' SCI')
    return len(rows)

def restore(raw):
    if len(raw)>100*1024*1024 or not raw.startswith(b'SQLite format 3\x00'): raise ValueError('Sauvegarde SQLite non valide (100 Mo maximum).')
    fd,p=tempfile.mkstemp(suffix='.db'); os.close(fd)
    try:
        Path(p).write_bytes(raw)
        src=connect(p)
        try:
            if src.execute('PRAGMA integrity_check').fetchone()[0]!='ok': raise ValueError('Base endommagée.')
            if src.execute("SELECT value FROM meta WHERE key='version'").fetchone()[0]!='1': raise ValueError('Version non prise en charge.')
            if src.execute('PRAGMA foreign_key_check').fetchone(): raise ValueError('Relations incohérentes.')
            json.loads(src.execute("SELECT value FROM meta WHERE key='settings'").fetchone()[0])
            for r in src.execute('SELECT * FROM scis'): clean('sci',json.loads(r['data']))
            for r in src.execute('SELECT * FROM records'):
                if r['kind'] not in KINDS: raise ValueError('Type de données inconnu.')
                d=clean(r['kind'],json.loads(r['data'])); validate_refs(src,r['sci'],d,r['id'])
            tables={t:[tuple(r) for r in src.execute('SELECT * FROM '+t)] for t in ['meta','scis','records','audit','imports']}
        finally: src.close()
        make_safety_backup()
        with connect() as c:
            for t in ['records','scis','meta','audit','imports']: c.execute('DELETE FROM '+t)
            for t,rows in tables.items():
                if rows: c.executemany('INSERT INTO '+t+' VALUES('+','.join('?' for _ in rows[0])+')',rows)
            audit(c,'Restauration','Sauvegarde complète restaurée ; copie préalable dans sauvegardes/.')
    except sqlite3.Error: raise ValueError('Ce fichier n’est pas une sauvegarde Dominis valide.')
    finally: Path(p).unlink(missing_ok=True)

def sync_exit():
    with LOCK:
        with connect() as c:
            if c.execute('PRAGMA integrity_check').fetchone()[0]!='ok': raise ValueError('Erreur d’intégrité. Fermeture annulée.')
            auto=settings(c).get('auto_backup',True)
            audit(c,'Fermeture','Écritures validées et intégrité SQLite vérifiée.')
        if auto: make_safety_backup()

